            ["HERNÉ REŽIMY", "JEDEN HRÁČ: VYBER ÚROVEŇ VÍRUSOV, RÝCHLOSŤ A HUDBU, PRECHÁDZAJ ÚROVNE A PREKONAJ SVOJ REKORD. BODY DÁVAJÚ IBA VÍRUSY: KAŽDÝ VÍRUS ZNIČENÝ V TOM ISTOM ŤAHU DÁ O 100 VIAC AKO PREDOŠLÝ. CPU VS: HRAJ PROTI POČÍTAČU. ONLINE VS: HRAJ PROTI SKUTOČNÝM HRÁČOM."],
            ["ZÁPASY VS", "VYHRÁ TEN, KTO AKO PRVÝ ZNIČÍ VŠETKY SVOJE VÍRUSY, PREHRÁ TEN, KOMU SA UPCHÁ FĽAŠA. AK V JEDNOM ŤAHU UROBÍŠ 2 ALEBO VIAC ZMIZNUTÍ (REŤAZ), POŠLEŠ SÚPEROVI 2 AŽ 4 TRESTNÉ KAPSULY."],
            ["ONLINE VS", "KAŽDÝ, KTO MÁ HRU OTVORENÚ, JE V ZOZNAME HRÁČOV. ŤUKNI NA HRÁČA A POZVI HO: POZVÁNKA UKÁŽE ÚROVEŇ VÍRUSOV A RÝCHLOSŤ A HRÁČ JU MÔŽE PRIJAŤ ALEBO ODMIETNUŤ DO {T} SEKÚND. RÝCHLA HRA ŤA SPÁRUJE S ČAKAJÚCIM HRÁČOM. OBNOVIŤ HNEĎ AKTUALIZUJE ZOZNAM. ODCHOD ZO ZÁPASU ALEBO ZATVORENIE HRY SA RÁTA AKO PREHRA."],
            ["BODY HODNOSTI", "KAŽDÝ ZAČÍNA S 1000 RP. VÝHRA DÁ +{P} RP, PREHRA VEZME {P} RP, REMÍZA NIČ NEMENÍ. HODNOSTI:{RANKS}"],
            ["ÚČET", "HRÁŠ AKO HOSŤ: MÔŽEŠ HRAŤ ONLINE, ALE HOSTIA NIE SÚ VO SVETOVOM PORADÍ. NA OBRAZOVKE ÚČTU MÔŽEŠ ZMAZAŤ ÚČET AJ VŠETKY JEHO ÚDAJE."],
            ["SÚKROMIE", "HRA ZOBRAZUJE REKLAMY GOOGLE ADMOB, KTORÝ MÔŽE ZBIERAŤ ÚDAJE SÚVISIACE S REKLAMAMI. PRE HRU ONLINE SA TVOJE MENO, BODY HODNOTENIA A VÝSLEDKY ZÁPASOV UKLADAJÚ NA NÁŠ SERVER; ODOSIELAJÚ SA AJ ANONYMNÉ ŠTATISTIKY POUŽÍVANIA (MODEL ZARIADENIA). PODROBNOSTI V ZÁSADÁCH OCHRANY SÚKROMIA."],
