        [
            ["MỤC TIÊU", "TIÊU DIỆT MỌI VIRUS TRONG LỌ. NHỮNG VIÊN NANG HAI MÀU RƠI TỪ TRÊN XUỐNG: DI CHUYỂN, XOAY VÀ THẢ CHÚNG. KHI 4 MẢNH CÙNG MÀU TRỞ LÊN (VIRUS HOẶC NỬA VIÊN NANG) XẾP THÀNH HÀNG NGANG HOẶC DỌC, CHÚNG BIẾN MẤT. DIỆT HẾT VIRUS ĐỂ QUA MÀN. NẾU VIÊN NANG LẤP KÍN CỔ LỌ, TRÒ CHƠI KẾT THÚC."],
            ["ĐIỀU KHIỂN", "TRÁI / PHẢI: DI CHUYỂN VIÊN NANG. XUỐNG: RƠI NHANH HƠN. NÚT XOAY: XOAY VIÊN NANG. II: TẠM DỪNG. BÀN PHÍM: CÁC PHÍM MŨI TÊN, LÊN ĐỂ XOAY, SPACE THẢ NGAY, ESC TẠM DỪNG."],
            ["CHẾ ĐỘ CHƠI", "CHƠI ĐƠN: CHỌN CẤP VIRUS, TỐC ĐỘ VÀ NHẠC, VƯỢT QUA CÁC MÀN VÀ PHÁ KỶ LỤC CỦA BẠN. CHỈ VIRUS MỚI CHO ĐIỂM: MỖI VIRUS BỊ DIỆT TRONG CÙNG MỘT NƯỚC ĐI CHO NHIỀU HƠN CON TRƯỚC 100 ĐIỂM. CPU VS: ĐẤU VỚI MÁY. ONLINE VS: ĐẤU VỚI NGƯỜI CHƠI THẬT."],
            ["TRẬN ĐẤU VS", "AI DIỆT HẾT VIRUS CỦA MÌNH TRƯỚC SẼ THẮNG, AI BỊ LẤP KÍN LỌ SẼ THUA. TẠO 2 LẦN XÓA TRỞ LÊN TRONG MỘT NƯỚC ĐI (CHUỖI) ĐỂ GỬI CHO ĐỐI THỦ 2 ĐẾN 4 VIÊN NANG PHẠT."],
            ["ONLINE VS", "MỌI NGƯỜI ĐANG MỞ TRÒ CHƠI ĐỀU HIỆN TRONG DANH SÁCH. CHẠM VÀO MỘT NGƯỜI CHƠI ĐỂ MỜI: LỜI MỜI GHI CẤP VIRUS VÀ TỐC ĐỘ, NGƯỜI ĐÓ CÓ THỂ CHẤP NHẬN HOẶC TỪ CHỐI TRONG {T} GIÂY. GHÉP NHANH SẼ GHÉP BẠN VỚI NGƯỜI ĐANG CHỜ. LÀM MỚI CẬP NHẬT DANH SÁCH NGAY. RỜI TRẬN HOẶC ĐÓNG TRÒ CHƠI SẼ BỊ TÍNH LÀ THUA."],
            ["ĐIỂM XẾP HẠNG", "AI CŨNG BẮT ĐẦU VỚI 1000 RP. THẮNG ĐƯỢC +{P} RP, THUA MẤT {P} RP, HÒA KHÔNG THAY ĐỔI GÌ. CÁC HẠNG:{RANKS}"],
            ["TÀI KHOẢN", "BẠN CHƠI VỚI TƯ CÁCH KHÁCH: BẠN CÓ THỂ CHƠI ONLINE, NHƯNG KHÁCH KHÔNG CÓ MẶT TRONG XẾP HẠNG THẾ GIỚI. Ở MÀN HÌNH TÀI KHOẢN, BẠN CÓ THỂ XÓA TÀI KHOẢN VÀ TOÀN BỘ DỮ LIỆU."],
            ["QUYỀN RIÊNG TƯ", "TRÒ CHƠI HIỂN THỊ QUẢNG CÁO TỪ GOOGLE ADMOB, CÓ THỂ THU THẬP DỮ LIỆU LIÊN QUAN ĐẾN QUẢNG CÁO. ĐỂ CHƠI ONLINE, TÊN NGƯỜI CHƠI, ĐIỂM XẾP HẠNG VÀ KẾT QUẢ TRẬN ĐẤU CỦA BẠN ĐƯỢC LƯU TRÊN MÁY CHỦ CỦA CHÚNG TÔI; THỐNG KÊ SỬ DỤNG ẨN DANH (MẪU THIẾT BỊ) CŨNG ĐƯỢC GỬI. XEM CHI TIẾT TRONG CHÍNH SÁCH QUYỀN RIÊNG TƯ."],
